const $=s=>document.querySelector(s);
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='nlp-learning-v1';
function lessonSearchText(l){
  const prose=[l.title,l.subtitle,l.goal,l.summary,...l.tags,...l.sections.flat(),...l.exercise,l.answer,...l.quiz.flat()];
  return (prose.join(' ').replace(/<[^>]*>/g,' ')+' '+(l.code||'')).normalize('NFKC').toLowerCase();
}
function bindDownloads(){
  document.querySelectorAll('[data-download]').forEach(button=>button.onclick=()=>{
    const name=button.dataset.download;
    if(!Object.prototype.hasOwnProperty.call(EXAMPLE_FILES,name))return;
    const url=URL.createObjectURL(new Blob([EXAMPLE_FILES[name]],{type:'text/plain;charset=utf-8'}));
    const link=document.createElement('a');link.href=url;link.download=name;document.body.appendChild(link);link.click();link.remove();
    setTimeout(()=>URL.revokeObjectURL(url),10000);
  });
}
function cleanPrintDocument(){
  document.getElementById('print-document')?.remove();
  document.body.classList.remove('print-all');
}
function preparePrintDocument(){
  cleanPrintDocument();
  const output=document.createElement('div');output.id='print-document';
  output.innerHTML='<p class="print-intro">NLP Learning Lab · 実験は各章の初期設定で計算した結果です。</p>'+home()+fieldsPage()+LESSONS.map((_,i)=>lesson(i,true)).join('');
  output.querySelectorAll('.lesson').forEach((root,i)=>initLab(LESSONS[i].lab,root,false));
  output.querySelectorAll('details').forEach(el=>el.open=true);
  output.querySelectorAll('.quiz .answer').forEach(button=>{
    const choice=document.createElement('div');choice.className='print-choice';choice.textContent=button.textContent;button.replaceWith(choice);
  });
  output.querySelectorAll('.lab input,.lab select,.lab textarea').forEach(input=>{
    const value=document.createElement('div');value.className='print-value';
    value.textContent=input.tagName==='SELECT'?input.selectedOptions[0].textContent:input.value;
    input.replaceWith(value);
  });
  output.querySelectorAll('button,.download-actions,.map-tools').forEach(el=>el.remove());
  // 各章の同名IDが画面側と衝突しないよう、計算後の印刷用要素から除きます。
  output.querySelectorAll('[id]').forEach(el=>el.removeAttribute('id'));
  output.querySelectorAll('[for]').forEach(el=>el.removeAttribute('for'));
  output.querySelectorAll('.field-page .sources').forEach(el=>el.insertAdjacentHTML('beforebegin','<p class="print-only">学習メモと進捗は印刷に含まれません。</p>'));
  document.body.appendChild(output);document.body.classList.add('print-all');
  return output;
}
let state={done:[],notes:{}};
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&Array.isArray(saved.done)&&saved.notes&&typeof saved.notes==='object')state=saved;}catch{}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));return true;}catch{return false;}}
function softmax(xs,t=1){const m=Math.max(...xs);const es=xs.map(x=>Math.exp((x-m)/t));const total=es.reduce((a,b)=>a+b,0);return es.map(x=>x/total);}
function bars(labels,values,scale=1){return `<div class="bars">${labels.map((l,i)=>`<div class="barrow"><span>${esc(l)}</span><div class="bartrack"><div class="barfill" style="width:${Math.max(0,Math.min(100,values[i]/scale*100))}%"></div></div><span>${values[i].toFixed(3)}</span></div>`).join('')}</div>`;}
function nav(){const query=$('#search').value.normalize('NFKC').trim().toLowerCase();const active=location.hash;$('#nav').innerHTML=`<a class="navitem ${active==='#home'||!active?'active':''}" href="#home"><span class="num">⌂</span>学習マップ</a><a class="navitem ${active==='#fields'?'active':''}" href="#fields"><span class="num">◇</span>NLPの分野マップ</a>`+LESSONS.map((l,i)=>({l,i})).filter(({l})=>lessonSearchText(l).includes(query)).map(({l,i})=>`<a class="navitem ${active===`#chapter-${i+1}`?'active':''} ${state.done.includes(i)?'done':''}" href="#chapter-${i+1}" ${active===`#chapter-${i+1}`?'aria-current="page"':''}><span class="num">${state.done.includes(i)?'✓':String(i+1).padStart(2,'0')}</span>${l.title}</a>`).join('');if(query&&$('#nav').children.length===2)$('#nav').insertAdjacentHTML('beforeend','<p class="empty">該当する章がありません。</p>');$('#count').textContent=`${state.done.length} / 12`;$('#progress').value=state.done.length;}
function home(){return `<div class="home"><div class="hero"><div><p class="eyebrow">Python経験者向け</p><h1>自然言語処理入門</h1><p class="lead">テキストの数値化から、分類・Transformer・RAGまでを、<br>図解と小さな実験で順に学びます。</p><a class="primary" href="#chapter-1">第1章から始める <span aria-hidden="true">↗</span></a></div><div class="hero-visual" aria-label="文章からトークン、ベクトル、予測への変換の図"><div class="visual-label">FROM WORDS TO NUMBERS</div><div class="sentence">「猫が好き」</div><div class="tokenrow"><span class="token">猫</span><span class="token">が</span><span class="token">好き</span></div><div class="arrow">↓</div><div class="vectorrow">${[0,1,2].map((v)=>`<div class="vector">${[18,28,11,34,22,15].map((h,i)=>`<i style="height:${(h+v*7+i*3)%30+8}px"></i>`).join('')}</div>`).join('')}</div><div class="arrow">↓</div><div class="output">数値表現を使って、分類・検索・生成を行う</div><small style="display:block;text-align:center;color:var(--muted);font-size:10px;margin-top:12px">概念図 · ベクトルは説明用です</small></div></div><div class="facts"><div><b>12</b><span>基礎から応用までの章</span></div><div><b>14</b><span>ブラウザで動かす実験</span></div><div><b>Python</b><span>基本文法の経験が前提</span></div></div><a class="field-teaser" href="#fields"><span>まずは全体像から</span><b>NLPには、どんな分野がある？</b><small>手法の4段階と応用 × 解く問題の地図 →</small></a><div class="sectionhead"><h2>学習マップ</h2><small>全12章を4つの段階に分けています。</small></div>${[['01','基礎','全体像・数の考え方・前処理',0,3],['02','表現と分類','BoW・評価・埋め込み',3,6],['03','系列とAttention','系列モデル・Attention・Transformer',6,9],['04','応用','LLM・RAG・実験',9,12]].map(([n,t,s,start,end])=>`<section class="phase"><div class="phase-label">PHASE ${n}<b>${t}</b>${s}</div><div class="cards">${LESSONS.slice(start,end).map((l,j)=>`<a class="chaptercard" href="#chapter-${start+j+1}"><span class="index">${String(start+j+1).padStart(2,'0')} ${state.done.includes(start+j)?'✓':''}</span><h3>${l.title}</h3><p>${l.subtitle}</p><small>学習時間の目安 ${l.time}分 <span aria-hidden="true">↗</span></small></a>`).join('')}</div></section>`).join('')}<div class="guide"><h3>学習の進め方（3ステップ）</h3><p><b>1. 図から入る。</b> 入力・出力と処理の流れを確認する。</p><p><b>2. 変えてみる。</b> 場面や条件を変え、結果を予想してから見る。</p><p><b>3. 説明して残す。</b> 理解チェックと演習に答え、メモに自分の説明を書く。</p><p><b>一周目は概念から：</b>具体例・図・実験・理解チェックを読み進めます。「数式で確認する」とPythonコードは任意です。二周目で計算や実装を確かめられます。</p><p>各章の時間は初めて学ぶ場合の学習時間の目安です。Pythonの実行は別の環境で行います。最終課題には追加の実装時間を取りましょう。</p></div><div class="sectionhead"><h2>4週間の進め方</h2><small>週3回＋復習。ペースは自由です。</small></div><div class="schedule">${['1〜3章：全体像・数の考え方・前処理','4〜6章：TF-IDF・評価・埋め込み','7〜9章：系列・Attention・Transformer','10〜12章：LLM・RAG・最終課題'].map((x,i)=>`<div><b>Week ${i+1}</b>${x}<br>章を読む → 演習 → 復習</div>`).join('')}</div><div class="sectionhead"><h2>深く学ぶための参考資料</h2></div><div class="sources"><p>教材は独自の入門解説です。詳細や実装仕様は各章の参考資料で確認できます。</p>${['slp','hf','attention','tfidf'].map(k=>`<a href="${SOURCES[k][1]}" target="_blank" rel="noopener">${SOURCES[k][0]} ↗</a>`).join('')}</div></div>`;}
function quizzesOf(l){return l.quizzes||[l.quiz];}
function lesson(i,print=false){const l=LESSONS[i];return `<article class="lesson" data-chapter="${i}"><div class="lesson-nav"><a href="#home">学習マップ</a> / 第${i+1}章</div><p class="eyebrow">CHAPTER ${String(i+1).padStart(2,'0')} / 12 · 学習時間の目安 ${l.time}分</p><h1>${l.title}</h1><p class="summary">${l.summary}</p><div class="tags">${l.tags.map(t=>`<span>${t}</span>`).join('')}</div><div class="objectives"><b>この章のゴール</b><p>${l.goal}</p></div>${l.sections.map(([t,b],j)=>`<section><h2><span style="color:var(--green);font:14px ui-monospace;margin-right:10px">${String(j+1).padStart(2,'0')}</span>${t}</h2>${b}</section>`).join('')}<div class="lab" id="lab-${i}"><span class="lab-heading">TRY IT YOURSELF</span>${labMarkup(l.lab)}</div>${l.code?`<details class="code-supplement"><summary>任意：Pythonで確かめる（自分の環境で実行）</summary><p>概念の理解だけなら、コードを実行せず先に進めます。準備の手順は第12章にあります。</p><div class="code-top"><span>Pythonで確かめる · 自分の環境で実行</span><button class="copy" data-i="${i}">コードをコピー</button></div><pre><code>${esc(l.code)}</code></pre></details>`:''}<div class="quiz"><h3>理解チェック</h3>${quizzesOf(l).map(([question,options,answer,why],k)=>`<div class="qitem" data-quiz-index="${k}"><p>Q${k+1}. ${question}</p>${options.map((option,j)=>`<button class="answer" data-i="${i}" data-answer="${j}">${String.fromCharCode(65+j)}. ${option}</button>`).join('')}<div class="feedback" role="status" aria-live="polite"></div><div class="print-only">正解：${options[answer]}。${why}</div></div>`).join('')}</div><section class="exercise"><h3>自分の手で考える</h3><ol>${l.exercise.map(x=>`<li>${x}</li>`).join('')}</ol><details ${print?'open':''}><summary>解答の例を見る</summary><p>${l.answer}</p></details></section>${l.takeaways?`<div class="takeaways"><h3>この章のまとめ</h3><ul>${l.takeaways.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></div>`:''}${print?'':`<div class="memo"><label for="memo">学習メモ</label><textarea id="memo" placeholder="今日理解したこと、まだ疑問なこと、自分の言葉での説明…">${esc(state.notes[i]||'')}</textarea><small id="memo-status" aria-live="polite">このブラウザ内だけに保存します。別端末には同期されません。</small></div><div class="lesson-bottom"><a href="${i?`#chapter-${i}`:'#home'}">← ${i?'前の章':'学習マップ'}</a><button class="primary" id="complete">${state.done.includes(i)?'✓ 完了済み（取り消す）':'この章を完了にする'}</button><a href="${i<11?`#chapter-${i+2}`:'#home'}">${i<11?'次の章':'学習マップ'} →</a></div>`}<div class="sources"><b>参考資料</b>${l.sources.map(k=>`<a href="${SOURCES[k][1]}" target="_blank" rel="noopener">${SOURCES[k][0]} ↗</a>`).join('')}</div></article>`;}
function labMarkup(kind){switch(kind){
case 'task':return '<h3>タスクを選び、入力と出力を確認</h3><label for="task">目的</label><select id="task"><option value="0">感情分類</option><option value="1">固有表現抽出</option><option value="2">文書検索</option><option value="3">翻訳</option></select><div class="labresult" id="result" aria-live="polite"></div>';
case 'softmax':case 'sampling':return `<h3>${kind==='sampling'?'温度を変えて、次トークンの分布を見る':'同じスコアでも、温度で確率は変わる'}</h3><p>候補「猫・犬・鳥」の架空のlogitは [2, 1, 0]。</p><label for="temperature">温度 T：<output id="temp-value">1.00</output></label><input id="temperature" type="range" min="0.1" max="3" step="0.05" value="1"><div class="labresult" id="result" aria-live="polite"></div>${kind==='sampling'?'<button id="sample">分布から1つ抽選する</button><span id="sampled" role="status"></span>':''}`;
case 'tokenize':return '<h3>同じ文章を、異なる単位で分割</h3><label for="text">文章（最大200文字）</label><input id="text" maxlength="200" value="ＡＩ について学ぶ"><label for="unit">分割単位</label><select id="unit"><option value="char">文字単位</option><option value="space">空白単位</option></select><p>これは分割の基本を観察する実験です。日本語の形態素解析・BPEは実行していません。</p><div class="labresult" id="result" aria-live="polite"></div>';
case 'tfidf':return '<h3>コーパスを変えて、IDFを確かめる</h3><label for="docs">1行1文書・語は空白区切り（最大2,000文字）</label><textarea id="docs" rows="3" maxlength="2000">猫 好き\n犬 好き\n猫 猫</textarea><p>TFは出現回数、IDFは本文の「実際に使う式」（scikit-learnの標準設定）で計算します。L2正規化はしません。先頭20語を表示します。</p><div class="labresult" id="result" aria-live="polite"></div>';
case 'metrics':return "<h3>迷惑メールを、どこまで拾う？</h3><p>迷惑メール20通・普通のメール80通がある架空の例です。判定の条件を切り替え、見逃しと誤検出がどう変わるか予想してください。実際のモデルは動かしていません。</p><label for=\"metric-scenario\">迷惑と判定する条件</label><select id=\"metric-scenario\"><option value=\"strict\">強い確信があるものだけ</option><option value=\"balanced\" selected>標準の条件</option><option value=\"broad\">疑わしいものも幅広く拾う</option></select><div class=\"labresult\" id=\"result\" aria-live=\"polite\"></div>";
case 'embedding':return "<h3>同じ「かける」を、どう表す？</h3><p>「電話をかける」と「眼鏡をかける」の表現を比べます。人が作った概念図で、モデルの推論や類似度計算は行っていません。</p><label for=\"embedding-mode\">表現の作り方</label><select id=\"embedding-mode\"><option value=\"static\">同じ語に、一つの表現を割り当てる</option><option value=\"contextual\">周りの文脈を反映した表現を作る</option></select><div class=\"labresult\" id=\"result\" aria-live=\"polite\"></div>";
case 'bigram':return '<h3>直前の1語で予測する</h3><p>架空の学習カウントに基づく、平滑化なしのbigramです。文頭・文末は省略しています。</p><label for="previous">直前の語</label><select id="previous"><option>猫</option><option>が</option><option>好き</option></select><div class="labresult" id="result" aria-live="polite"></div>';
case 'attention':return "<h3>「それ」に、どの語の情報を取り込む？</h3><p>参照先を切り替える概念デモです。人が選んだ語の情報を取り込む図であり、実際のAttentionの重みを計算するものではありません。</p><label for=\"attention-scene\">文の場面</label><select id=\"attention-scene\"><option value=\"cake\">彼女はケーキを買い、それを食べた</option><option value=\"book\">彼女は本を借り、それを読んだ</option></select><label for=\"attention-focus\">「それ」が取り込む情報の参照先</label><select id=\"attention-focus\"><option value=\"object\">ケーキ／本</option><option value=\"person\">彼女</option></select><div class=\"labresult\" id=\"result\" aria-live=\"polite\"></div>";
case 'mask':return '<h3>どの位置が、どの位置を参照できる？</h3><label for="mask">マスク</label><select id="mask"><option value="causal">causal：過去と自分だけ</option><option value="full">全位置：双方向</option></select><p>行はQuery、列はKey。●は参照できる位置、—は参照できない位置です。</p><div class="labresult" id="result"></div>';
case 'rag':return '<h3>検索された根拠を確認する</h3><p>3件の架空の講座案内を対象にした文字2-gramのJaccard類似度検索。LLMによる回答生成は行いません。</p><label for="query">質問</label><input id="query" maxlength="200" value="講座の開催日は？"><div class="labresult" id="result" aria-live="polite"></div>';
case 'experiment':return '<h3>実験計画を組み立てる</h3><p>この欄は下の学習メモとは別です。計画をコピーして手元に保存できます。</p>'+[['purpose','入力 → 出力','レビュー → 肯定 / 否定'],['baseline','ベースライン','多数派予測、TF-IDF＋ロジスティック回帰'],['evaluation','評価・分割','macro F1、重複を除いた固定分割']].map(([id,t,v])=>`<label for="${id}">${t}</label><input id="${id}" maxlength="500" value="${v}">`).join('')+'<div class="labresult" id="result"></div><button id="copy-plan">計画をコピー</button><span id="plan-status" role="status"></span>';
}}
function initLab(kind, root=document, interactive=true){const $=s=>root.querySelector(s);const result=$('#result');const update=()=>{switch(kind){
case 'task':{const k=Number($('#task').value);result.innerHTML=[['レビュー：「とても面白かった」','出力：肯定','評価：F1・混同行列'],['文章：「田中さんは東京で働く」','出力：田中→人名、東京→地名','評価：範囲とラベルの一致'],['質問：「NLPの教材は？」','出力：関連文書を順位付きで返す','評価：Recall@k・MRR'],['原文：「猫が好きです」','出力：I like cats.','評価：自動指標と人による評価']][k].map(x=>`<div>${x}</div>`).join('');break;}
case 'softmax':case 'sampling':{const t=Number($('#temperature').value);$('#temp-value').value=t.toFixed(2);const ps=softmax([2,1,0],t);result.innerHTML=bars(['猫','犬','鳥'],ps)+`<p><b>${t<0.7?'一位の「猫」に確率が集中しています。':t>1.7?'候補の確率の差が縮まり、「犬」「鳥」も選ばれやすくなります。':'「猫」が一位ですが、ほかの候補にも確率があります。'}</b></p><p>温度を変えてもスコアの順位は同じです。候補にどれくらい確率を配るかが変わります。${kind==='sampling'?'抽選では、一位以外が出ることもあります。':'ここでは正解を「猫」と考えます。「猫」に高い確率を付けるほど、損失は小さくなります。'}</p>`+ (kind==='softmax'?mathbox(`<p>確率の合計：${ps.reduce((a,b)=>a+b,0).toFixed(3)}。正解が猫なら交差エントロピー損失：${(-Math.log(ps[0])).toFixed(3)}。</p>`):'');break;}
case 'tokenize':{const s=$('#text').value;const normalized=s.normalize('NFKC').replace(/\s+/g,' ').trim();const tokens=$('#unit').value==='char'?Array.from(normalized).filter(x=>!(/\s/.test(x))):normalized.split(/\s+/).filter(Boolean);result.innerHTML=`<p>正規化後：${esc(normalized)||'（空）'}</p><div class="tokenrow" style="justify-content:flex-start">${tokens.map(t=>`<span class="token">${esc(t)}</span>`).join('')}</div><p>${tokens.length} トークン${$('#unit').value==='char'?'（空白は除外）':''}</p>`;break;}
case 'tfidf':{const docs=$('#docs').value.split('\n').map(d=>d.trim().split(/\s+/).filter(Boolean)).filter(d=>d.length);if(!docs.length){result.textContent='文書を入力してください。';break;}const vocab=[...new Set(docs.flat())].slice(0,20);result.innerHTML=table(['語','df','IDF',...docs.map((_,i)=>`文書${i+1} TF-IDF`)],vocab.map(t=>{const df=docs.filter(d=>d.includes(t)).length;const idf=Math.log((docs.length+1)/(df+1))+1;return [esc(t),df,idf.toFixed(3),...docs.map(d=>(d.filter(x=>x===t).length*idf).toFixed(3))];}));const rare=vocab.reduce((best,t)=>docs.filter(d=>d.includes(t)).length<docs.filter(d=>d.includes(best)).length?t:best);const df=docs.filter(d=>d.includes(rare)).length;result.innerHTML+=`<p><b>「${esc(rare)}」は${docs.length}文書中${df}文書に出ています。</b></p><p>${df===docs.length?'どの文書にも出るので、この語だけでは文書を見分けにくくなります。':'同じ出現回数なら、多くの文書に出る語より強く目立たせる手掛かりになります。'} 文書を追加して、この語がありふれた語になるとどう変わるか確かめましょう。</p>`;break;}
case 'metrics':{const scenario=$('#metric-scenario').value;const [tp,fp,fn,tn]={strict:[10,1,10,79],balanced:[16,4,4,76],broad:[19,20,1,60]}[scenario];const p=tp/(tp+fp),r=tp/(tp+fn);result.innerHTML=table(['結果','通数','何が起きた？'],[['正しく検出（TP）',tp,'迷惑メールを止めた'],['見逃し（FN）',fn,'迷惑メールが受信箱へ届いた'],['誤検出（FP）',fp,'普通のメールを誤って止めた'],['正しく通した（TN）',tn,'普通のメールが受信箱へ届いた']])+`<p><b>${scenario==='strict'?'誤検出は少ない一方、迷惑メールの半分を見逃します。':scenario==='broad'?'見逃しは減りましたが、普通のメール20通も止めています。':'見逃しと誤検出が、それぞれ4通あります。'}</b></p><p>Precision（判定したものの正しさ）：${Math.round(p*100)}%。Recall（迷惑メールを拾えた割合）：${Math.round(r*100)}%。</p><p>大事なメールを止める害と、迷惑メールを通す害を比べ、使う目的に合う条件を選びます。この架空の結果は、特定のしきい値の実測値ではありません。</p>`;break;}
case 'embedding':{const contextual=$('#embedding-mode').value==='contextual';result.innerHTML=table(['入力の文','「かける」の表現をどう作る？'],[['電話をかける',contextual?'周囲の「電話」を反映した表現':'同じ語IDに割り当てた表現'],['眼鏡をかける',contextual?'周囲の「眼鏡」を反映した表現':'同じ語IDに割り当てた表現']])+(contextual?'<div class="bert-tokens"><div class="bert-token">表現A<small>電話の文脈を反映</small></div><div class="bert-token">表現B<small>眼鏡の文脈を反映</small></div></div>':flow(['電話／眼鏡のどちらでも','同じ「かける」の表現']))+`<p><b>${contextual?'同じ語でも、周囲の違いを出力の表現に反映できます。':'この段階では、同じ語に同じ表現を使います。二つの意味は区別されていません。'}</b></p><p>${contextual?'BERTなどでは、入力の埋め込みを文脈を使って加工し、トークンごとの表現を作ります。意味を完全に理解できる保証ではありません。':'Word2Vecなどの静的な単語表現を示しています。この表現を別の文脈処理のモデルに渡すことはできます。'}</p>`;break;}
case 'bigram':{const k=$('#previous').value;const data={'猫':[['が','は'],[3,1]],'が':[['好き','走る'],[2,2]],'好き':[['です','だ'],[4,1]]};const [ls,cs]=data[k];result.innerHTML=`<p>「${k}」の後のカウント：${ls.map((l,i)=>`${l}=${cs[i]}`).join('、')}</p>`+bars(ls,cs.map(c=>c/cs.reduce((a,b)=>a+b,0)));break;}
case 'attention':{const cake=$('#attention-scene').value==='cake',object=$('#attention-focus').value==='object';const target=object?(cake?'ケーキ':'本'):'彼女';result.innerHTML=flow([`参照先：${target}`,`取り込む内容：${target}の情報`,'「それ」の表現へ'])+`<p><b>${object?`「それ」が指す${target}の情報を取り込むと、何を${cake?'食べた':'読んだ'}かを表す手掛かりになります。`:'人物の情報を取り込む設定にしましたが、何を食べた／読んだのかを表す手掛かりは不足します。'}</b></p><p>Queryは「それ」の位置が探す情報、Keyは参照先を照合する目印、Valueは取り込む内容、と考えます。実際には複数の位置のValueを重みに応じて混ぜます。この図は参照先の役割を一つずつ見るための簡略化です。</p>`;break;}
case 'mask':{const full=$('#mask').value==='full',words=['彼女','は','ケーキ','を','食べた'];result.innerHTML=table(['参照する位置 ↓ / 参照先 →',...words.map((w,i)=>`${i+1}：${w}`)],words.map((w,i)=>[`${i+1}：${w}`,...words.map((_,j)=>full||j<=i?'●':'—')]))+`<p><b>3番目の「ケーキ」は、${full?'後ろの「を」「食べた」も参照できます。':'自分までの位置だけを参照し、後ろの「を」「食べた」は参照できません。'}</b></p><p>「未来」は、ここでは入力の後ろにあるトークンのことです。次を予測する学習では、後ろの正解を見せないようにします。</p>`;break;}
case 'rag':{const docs=['講座の開催日は11月1日です。','講座の参加費は無料です。','講座の場所はオンラインです。'];const grams=s=>{const a=Array.from(s.replace(/[\s？?。、]/g,''));return new Set(a.slice(0,-1).map((c,i)=>c+a[i+1]));};const q=grams($('#query').value);const ranked=docs.map((d,i)=>{const g=grams(d);const intersection=[...q].filter(t=>g.has(t)).length;const union=new Set([...q,...g]).size;return {d,i,score:union?intersection/union:0};}).sort((a,b)=>b.score-a.score);result.innerHTML=ranked.map((r,i)=>`<p><b>${i+1}位 · 文書${r.i+1}</b> / 類似度 ${r.score.toFixed(3)}<br>${esc(r.d)}</p>`).join('')+'<p>スコアは回答の確かさではありません。関係がない質問でも候補が並ぶので、根拠の有無を確認します。</p>';break;}
case 'experiment':{result.textContent=`入力・出力：${$('#purpose').value}\nベースライン：${$('#baseline').value}\n評価・分割：${$('#evaluation').value}`;result.style.whiteSpace='pre-wrap';break;}
}};update();if(!interactive)return;result.closest('.lab').querySelectorAll('input,select,textarea').forEach(el=>el.addEventListener('input',update));if(kind==='sampling')$('#sample').onclick=()=>{const ps=softmax([2,1,0],Number($('#temperature').value)),r=Math.random();let sum=0,index=2;for(let j=0;j<ps.length;j++){sum+=ps[j];if(r<sum){index=j;break;}}$('#sampled').textContent=` → 抽選結果：${['猫','犬','鳥'][index]}`;};if(kind==='experiment')$('#copy-plan').onclick=()=>copyText(result.textContent,$('#plan-status'));}
async function copyText(text,target){try{await navigator.clipboard.writeText(text);target.textContent='コピーしました';}catch{target.textContent='コピーできません。表示された本文を選択してコピーしてください。';}}
function render(focus=false){nav();const match=location.hash.match(/^#chapter-(\d+)$/);const i=match?Number(match[1])-1:-1;if(location.hash==='#fields'){$('#main').innerHTML=fieldsPage();document.title='NLPの分野マップ｜NLP Learning Lab';initFields();}else if(i<0||i>=LESSONS.length){$('#main').innerHTML=home();document.title='自然言語処理入門｜NLP Learning Lab';}else{const l=LESSONS[i];$('#main').innerHTML=lesson(i);document.title=`第${i+1}章 ${l.title}｜NLP Learning Lab`;initLab(l.lab);$('#complete').onclick=()=>{state.done=state.done.includes(i)?state.done.filter(v=>v!==i):[...state.done,i];const stored=save();nav();$('#complete').textContent=state.done.includes(i)?'✓ 完了済み（取り消す）':'この章を完了にする';if(!stored)$('#memo-status').textContent='ブラウザ保存が使えないため、再読込すると進捗が消えます。';};$('#memo').oninput=()=>{state.notes[i]=$('#memo').value;$('#memo-status').textContent=save()?'メモをこのブラウザに保存しました。':'保存できません。メモをコピーして手元に残してください。';};document.querySelectorAll('.qitem').forEach(item=>{const [, , answer,why]=quizzesOf(l)[Number(item.dataset.quizIndex)];item.querySelectorAll('.answer').forEach(btn=>btn.onclick=()=>{const correct=Number(btn.dataset.answer)===answer;item.querySelectorAll('.answer').forEach(b=>b.classList.remove('correct','wrong'));btn.classList.add(correct?'correct':'wrong');item.querySelector('.feedback').textContent=(correct?'正解です。':'もう一度考えてみましょう。')+' '+why;});});if(l.code)$('.copy').onclick=()=>copyText(l.code,$('.copy'));bindDownloads();}if(focus){window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});}}
$('#search').oninput=nav;
$('.skip').onclick=e=>{e.preventDefault();$('#main').focus();};
window.addEventListener('hashchange',()=>render(true));
$('#print').onclick=()=>{preparePrintDocument();window.print();};
window.addEventListener('afterprint',cleanPrintDocument);
render();
